//! Golden tests for `plane_serde::pyjson` against the pinned DRF/CPython.
//!
//! The corpus is generated by `apps/server/tools/golden/pyjson_corpus.py`,
//! which feeds every body through the real
//! `rest_framework.parsers.JSONParser().parse` in `apps/api/.venv`. Each line
//! records either the exact Python value (as a tagged description), the bytes
//! DRF's `JSONRenderer` produces for it and the bytes Django's encoder
//! produces, or the exact exception class and message.
//!
//! The whole test runs on a thread with a large stack: deep-nesting cases
//! parse to a value ~9997 levels deep, and although the parser and the value's
//! `Drop` are iterative, the serialiser and this test's own comparisons are
//! not.

use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};

use plane_serde::pyjson::{LoadError, LoadErrorKind, Value, loads};
use plane_serde::{Dialect, Error, to_vec};

// ---------------------------------------------------------------------------
// Record
// ---------------------------------------------------------------------------

#[derive(Debug, serde::Deserialize)]
struct Record {
    cat: String,
    #[serde(rename = "in")]
    input: String,
    enc: String,
    ok: bool,
    #[serde(default)]
    value: Option<serde_json::Value>,
    #[serde(default)]
    deep: Option<Deep>,
    #[serde(default)]
    drf: Option<String>,
    #[serde(default)]
    drf_error: Option<RenderError>,
    #[serde(default)]
    django: Option<String>,
    #[serde(default)]
    error: Option<ParseFailure>,
}

#[derive(Debug, serde::Deserialize)]
struct Deep {
    kinds: String,
    leaf: serde_json::Value,
}

#[derive(Debug, serde::Deserialize)]
struct RenderError {
    #[serde(rename = "type")]
    exception: String,
    msg: String,
}

#[derive(Debug, serde::Deserialize)]
struct ParseFailure {
    #[serde(rename = "type")]
    exception: String,
    #[serde(default)]
    detail: Option<String>,
    #[serde(default)]
    msg: Option<String>,
    kind: String,
}

fn kind_of(name: &str) -> LoadErrorKind {
    match name {
        "charset" => LoadErrorKind::Charset,
        "decode" => LoadErrorKind::Decode,
        "json" => LoadErrorKind::Json,
        "recursion" => LoadErrorKind::Recursion,
        other => panic!("unknown failure kind {other}"),
    }
}

// ---------------------------------------------------------------------------
// Tagged values
// ---------------------------------------------------------------------------

/// Compare a parsed value with the tagged description the generator wrote.
fn matches_tagged(value: &Value, tagged: &serde_json::Value) -> Result<(), String> {
    let object = tagged
        .as_object()
        .ok_or_else(|| format!("tagged value is not an object: {tagged}"))?;
    let tag = object
        .get("t")
        .and_then(serde_json::Value::as_str)
        .ok_or_else(|| format!("tagged value has no tag: {tagged}"))?;
    match tag {
        "null" => match value {
            Value::Null => Ok(()),
            other => Err(format!("expected null, got {other:?}")),
        },
        "bool" => {
            let expected = object.get("v").and_then(serde_json::Value::as_bool);
            match value.as_bool() {
                Some(actual) if Some(actual) == expected => Ok(()),
                _ => Err(format!("expected bool {expected:?}, got {value:?}")),
            }
        }
        "int" => {
            let expected = object
                .get("v")
                .and_then(serde_json::Value::as_str)
                .ok_or_else(|| "int tag has no value".to_owned())?;
            let Some(integer) = value.as_int() else {
                return Err(format!("expected int {expected}, got {value:?}"));
            };
            if integer.to_decimal_string() == expected {
                Ok(())
            } else {
                Err(format!("expected int {expected}, got {integer}"))
            }
        }
        "float" => {
            let text = object
                .get("v")
                .and_then(serde_json::Value::as_str)
                .ok_or_else(|| "float tag has no value".to_owned())?;
            if text.len() != 16 {
                return Err(format!("float tag is not 8 bytes of hex: {text}"));
            }
            let mut bytes = [0u8; 8];
            for (index, byte) in bytes.iter_mut().enumerate() {
                *byte = u8::from_str_radix(&text[index * 2..index * 2 + 2], 16)
                    .map_err(|error| error.to_string())?;
            }
            // The generator stores the eight little-endian bytes of the double.
            let expected = f64::from_le_bytes(bytes);
            match value.as_f64() {
                Some(actual) if actual.to_bits() == expected.to_bits() => Ok(()),
                _ => Err(format!(
                    "expected float bits {:#x}, got {:?}",
                    expected.to_bits(),
                    value.as_f64().map(f64::to_bits)
                )),
            }
        }
        "str" => {
            let text = object
                .get("v")
                .and_then(serde_json::Value::as_str)
                .ok_or_else(|| "str tag has no value".to_owned())?;
            let expected = decode_base64(text);
            match value.as_pystr() {
                Some(actual) if actual.as_wtf8() == expected.as_slice() => Ok(()),
                _ => Err(format!(
                    "expected string {:?}, got {:?}",
                    expected,
                    value.as_pystr().map(plane_serde::pyjson::PyStr::as_wtf8)
                )),
            }
        }
        "arr" => {
            let items = object
                .get("v")
                .and_then(serde_json::Value::as_array)
                .ok_or_else(|| "arr tag has no value".to_owned())?;
            let Some(actual) = value.as_list() else {
                return Err(format!("expected a list, got {value:?}"));
            };
            if actual.len() != items.len() {
                return Err(format!(
                    "expected {} items, got {}",
                    items.len(),
                    actual.len()
                ));
            }
            for (index, (actual, expected)) in actual.iter().zip(items).enumerate() {
                matches_tagged(actual, expected).map_err(|error| format!("[{index}]: {error}"))?;
            }
            Ok(())
        }
        "obj" => {
            let entries = object
                .get("v")
                .and_then(serde_json::Value::as_array)
                .ok_or_else(|| "obj tag has no value".to_owned())?;
            let Some(actual) = value.as_dict() else {
                return Err(format!("expected an object, got {value:?}"));
            };
            if actual.len() != entries.len() {
                return Err(format!(
                    "expected {} members, got {}",
                    entries.len(),
                    actual.len()
                ));
            }
            for (index, (entry, (key, value))) in entries.iter().zip(actual.iter()).enumerate() {
                let pair = entry
                    .as_array()
                    .ok_or_else(|| format!("object entry is not a pair: {entry}"))?;
                if pair.len() != 2 {
                    return Err(format!("object entry is not a pair: {entry}"));
                }
                let expected_key = pair[0]
                    .as_object()
                    .and_then(|object| object.get("v"))
                    .and_then(serde_json::Value::as_str)
                    .ok_or_else(|| "object key is not a string tag".to_owned())?;
                let expected_key = decode_base64(expected_key);
                if key.as_wtf8() != expected_key.as_slice() {
                    return Err(format!(
                        "member {index}: expected key {expected_key:?}, got {:?}",
                        key.as_wtf8()
                    ));
                }
                matches_tagged(value, &pair[1])
                    .map_err(|error| format!("member {index}: {error}"))?;
            }
            Ok(())
        }
        other => Err(format!("unknown tag {other}")),
    }
}

/// Walk the single-child path of a deep value and check its shape.
fn matches_deep(value: &Value, deep: &Deep) -> Result<(), String> {
    let mut current = value;
    for (level, kind) in deep.kinds.chars().enumerate() {
        match kind {
            'a' => {
                let Some(items) = current.as_list() else {
                    return Err(format!("level {level}: expected a list, got {current:?}"));
                };
                if items.len() != 1 {
                    return Err(format!(
                        "level {level}: expected one item, got {}",
                        items.len()
                    ));
                }
                current = &items[0];
            }
            'o' => {
                let Some(dict) = current.as_dict() else {
                    return Err(format!(
                        "level {level}: expected an object, got {current:?}"
                    ));
                };
                if dict.len() != 1 {
                    return Err(format!(
                        "level {level}: expected one member, got {}",
                        dict.len()
                    ));
                }
                current = dict.values().next().expect("one member");
            }
            other => return Err(format!("unknown kind {other}")),
        }
    }
    matches_tagged(current, &deep.leaf).map_err(|error| format!("leaf: {error}"))
}

// ---------------------------------------------------------------------------
// Runner
// ---------------------------------------------------------------------------

#[derive(Default)]
struct Summary {
    cases: usize,
    parsed: usize,
    failures: usize,
    mismatches: Vec<String>,
    counts: std::collections::BTreeMap<String, usize>,
}

fn corpus_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/pyjson/corpus.jsonl")
}

fn run_case(record: &Record, summary: &mut Summary) {
    let body = decode_base64(&record.input);
    let result = loads(&body, &record.enc);
    match (result, record.ok) {
        (Ok(value), true) => {
            summary.parsed += 1;
            if let Some(deep) = &record.deep {
                if let Err(error) = matches_deep(&value, deep) {
                    summary.mismatches.push(format!(
                        "MISMATCH cat={} enc={} deep: {error}\n  input: {}",
                        record.cat,
                        record.enc,
                        display_bytes(&body)
                    ));
                    return;
                }
            } else if let Some(tagged) = &record.value {
                if let Err(error) = matches_tagged(&value, tagged) {
                    summary.mismatches.push(format!(
                        "MISMATCH cat={} enc={} value: {error}\n  input: {}",
                        record.cat,
                        record.enc,
                        display_bytes(&body)
                    ));
                    return;
                }
            } else {
                summary.mismatches.push(format!(
                    "MISMATCH cat={}: record has neither value nor deep",
                    record.cat
                ));
                return;
            }

            // The DRF echo.
            match (to_vec(Dialect::Drf, &value), &record.drf, &record.drf_error) {
                (Ok(bytes), Some(expected), None) => {
                    let expected = decode_base64(expected);
                    if bytes != expected {
                        summary.mismatches.push(format!(
                            "MISMATCH cat={} drf render\n  input:    {}\n  expected: {}\n  got:      {}",
                            record.cat,
                            display_bytes(&body),
                            display_bytes(&expected),
                            display_bytes(&bytes)
                        ));
                    }
                }
                (Err(error), None, Some(expected)) => {
                    let actual = match &error {
                        Error::NonFinite(value) => format!(
                            "Out of range float values are not JSON compliant: {}",
                            python_repr(*value)
                        ),
                        Error::Custom(message) => message.clone(),
                        other => format!("{other:?}"),
                    };
                    if actual != expected.msg {
                        summary.mismatches.push(format!(
                            "MISMATCH cat={} drf render error\n  expected ({}): {}\n  got: {}",
                            record.cat, expected.exception, expected.msg, actual
                        ));
                    }
                }
                (Ok(bytes), _, Some(expected)) => {
                    summary.mismatches.push(format!(
                        "MISMATCH cat={} drf render: expected an error ({}), got {}",
                        record.cat,
                        expected.msg,
                        display_bytes(&bytes)
                    ));
                }
                (Err(error), _, None) => {
                    summary.mismatches.push(format!(
                        "MISMATCH cat={} drf render: unexpected error {error:?}",
                        record.cat
                    ));
                }
                (Ok(_), None, None) | (Err(_), Some(_), _) => {
                    summary.mismatches.push(format!(
                        "MISMATCH cat={} drf render: record has no drf output",
                        record.cat
                    ));
                }
            }

            // The Django encoder.
            if let Some(expected) = &record.django {
                let expected = decode_base64(expected);
                match to_vec(Dialect::Django, &value) {
                    Ok(bytes) if bytes == expected => {}
                    Ok(bytes) => summary.mismatches.push(format!(
                        "MISMATCH cat={} django render\n  input:    {}\n  expected: {}\n  got:      {}",
                        record.cat,
                        display_bytes(&body),
                        display_bytes(&expected),
                        display_bytes(&bytes)
                    )),
                    Err(error) => summary.mismatches.push(format!(
                        "MISMATCH cat={} django render: unexpected error {error:?}",
                        record.cat
                    )),
                }
            }
        }
        (Err(error), false) => {
            summary.failures += 1;
            let expected = record.error.as_ref().expect("error record");
            let mut problems = Vec::new();
            if error.kind() != kind_of(&expected.kind) {
                problems.push(format!(
                    "kind: expected {:?}, got {:?}",
                    kind_of(&expected.kind),
                    error.kind()
                ));
            }
            match expected.exception.as_str() {
                "RecursionError" => {
                    let expected_message = expected.msg.as_deref().unwrap_or_default();
                    if error.message() != expected_message {
                        problems.push(format!(
                            "message: expected {expected_message:?}, got {:?}",
                            error.message()
                        ));
                    }
                }
                "ParseError" => {
                    let expected_detail = expected.detail.as_deref().unwrap_or_default();
                    match error.parse_error_detail() {
                        Some(actual) if actual == expected_detail => {}
                        Some(actual) => problems.push(format!(
                            "detail: expected {expected_detail:?}, got {actual:?}"
                        )),
                        None => problems.push(format!(
                            "detail: expected a ParseError, got no detail ({error:?})"
                        )),
                    }
                }
                other => problems.push(format!("unexpected exception class {other}")),
            }
            if !problems.is_empty() {
                summary.mismatches.push(format!(
                    "MISMATCH cat={} enc={}: {}\n  input: {}",
                    record.cat,
                    record.enc,
                    problems.join("; "),
                    display_bytes(&body)
                ));
            }
        }
        (Ok(value), false) => {
            summary.mismatches.push(format!(
                "MISMATCH cat={} enc={}: expected {}{}, got {value:?}\n  input: {}",
                record.cat,
                record.enc,
                record
                    .error
                    .as_ref()
                    .map(|error| format!("{} ", error.exception))
                    .unwrap_or_default(),
                record
                    .error
                    .as_ref()
                    .and_then(|error| error.detail.clone().or_else(|| error.msg.clone()))
                    .unwrap_or_default(),
                display_bytes(&body)
            ));
        }
        (Err(error), true) => {
            summary.mismatches.push(format!(
                "MISMATCH cat={} enc={}: unexpected {error:?}\n  input: {}",
                record.cat,
                record.enc,
                display_bytes(&body)
            ));
        }
    }
}

fn python_repr(value: f64) -> &'static str {
    if value.is_nan() {
        "nan"
    } else if value == f64::INFINITY {
        "inf"
    } else {
        "-inf"
    }
}

fn run_corpus() -> Summary {
    let path = corpus_path();
    let contents = fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("read {}: {error}", path.display()));
    let mut summary = Summary::default();
    for (line_number, line) in contents.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let record: Record = serde_json::from_str(line).unwrap_or_else(|error| {
            panic!(
                "{}:{}: bad record: {error}",
                path.display(),
                line_number + 1
            )
        });
        *summary.counts.entry(record.cat.clone()).or_default() += 1;
        summary.cases += 1;
        run_case(&record, &mut summary);
    }
    summary
}

#[test]
fn pyjson_golden_corpus() {
    // Deep cases need room for the serialiser's recursion; everything else is
    // iterative. 256 MiB of address space is free on every platform we run.
    let summary = std::thread::Builder::new()
        .name("pyjson-golden".to_owned())
        .stack_size(256 * 1024 * 1024)
        .spawn(run_corpus)
        .expect("spawn golden thread")
        .join()
        .expect("golden corpus panicked");

    println!(
        "pyjson corpus: {} cases ({} parsed, {} rejected)",
        summary.cases, summary.parsed, summary.failures
    );
    println!("per category:");
    for (category, count) in &summary.counts {
        println!("  {category:24} {count:6}");
    }
    assert!(
        summary.cases >= 3_000,
        "corpus shrank to {} cases",
        summary.cases
    );

    if !summary.mismatches.is_empty() {
        let shown = summary.mismatches.len().min(25);
        let mut message = String::new();
        writeln!(
            message,
            "{} mismatches (showing {shown}):",
            summary.mismatches.len()
        )
        .expect("write to string");
        for mismatch in &summary.mismatches[..shown] {
            writeln!(message, "{mismatch}").expect("write to string");
        }
        panic!("{message}");
    }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

fn display_bytes(bytes: &[u8]) -> String {
    let capped = &bytes[..bytes.len().min(240)];
    match std::str::from_utf8(capped) {
        Ok(text) => format!(
            "{text:?}{}",
            if bytes.len() > capped.len() {
                "…"
            } else {
                ""
            }
        ),
        Err(_) => format!(
            "{:?}{}",
            capped,
            if bytes.len() > capped.len() {
                "…"
            } else {
                ""
            }
        ),
    }
}

/// Standard base64 with padding, as the generator writes it.
fn decode_base64(text: &str) -> Vec<u8> {
    fn value(byte: u8) -> Option<u8> {
        match byte {
            b'A'..=b'Z' => Some(byte - b'A'),
            b'a'..=b'z' => Some(byte - b'a' + 26),
            b'0'..=b'9' => Some(byte - b'0' + 52),
            b'+' => Some(62),
            b'/' => Some(63),
            _ => None,
        }
    }

    let bytes = text.as_bytes();
    let mut out = Vec::with_capacity(bytes.len() / 4 * 3);
    let mut accumulator: u32 = 0;
    let mut bits = 0;
    for &byte in bytes {
        if byte == b'=' {
            continue;
        }
        let value = value(byte).unwrap_or_else(|| panic!("invalid base64 byte {byte}"));
        accumulator = (accumulator << 6) | u32::from(value);
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((accumulator >> bits) as u8);
        }
    }
    out
}

#[test]
fn error_kinds_are_distinct() {
    // A small guard against the corpus silently encoding the same kind for
    // everything: the generator must exercise every layer.
    let path = corpus_path();
    let contents = fs::read_to_string(&path).expect("corpus exists");
    let mut kinds = std::collections::BTreeSet::new();
    for line in contents.lines() {
        let record: Record = serde_json::from_str(line).expect("record");
        if let Some(error) = record.error {
            kinds.insert(error.kind);
        }
    }
    for kind in ["charset", "decode", "json", "recursion"] {
        assert!(kinds.contains(kind), "corpus has no {kind} failures");
    }
    let _: fn(&LoadError) -> LoadErrorKind = LoadError::kind;
}
